insert into public.rating_dimensions (id, organization_id, key, label, parent_label, description, anchors, weight, enabled, sort_order, icon) values
  ('5f0dbd8a-9099-4c30-921a-b97b20f9e0cd', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'engagement', 'Engagement', 'Engagement', 'How much the child took part in the session activities.', '{"1":"Refused or withdrawn most of the session","2":"Joined briefly, mostly needed coaxing","3":"Participated with frequent redirection","4":"Participated well with occasional redirection","5":"Actively participated and initiated activities"}', 1, true, 1, 'sparkles'),
  ('8befa47d-63f4-40f5-8c8a-109dc65096e5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'attention', 'Attention / Focus', 'Focus', 'How long the child could stay with a task.', '{"1":"Could not stay on task beyond brief moments","2":"Stayed on task for very short spells with constant support","3":"Sustained attention for short blocks with redirection","4":"Sustained attention for most blocks with light support","5":"Sustained attention through full activity blocks"}', 1, true, 2, 'target'),
  ('95b44d3d-7d54-4fc0-8b3d-4af45a22d665', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'regulation', 'Regulation', 'Calmness', 'How well the child stayed regulated. Energy state is recorded separately.', '{"1":"Could not be regulated","2":"Regulated only briefly with full support","3":"Regulated with significant support","4":"Regulated with light support","5":"Self-regulated or stayed regulated"}', 1, true, 3, 'waves'),
  ('523a00a2-1254-4ad2-a5ce-607137e761f5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'mood', 'Mood / Affect', 'Mood', 'Overall emotional state during the session.', '{"1":"Distressed or crying most of the session","2":"Upset for long stretches","3":"Neutral or variable","4":"Mostly content","5":"Happy and settled"}', 1, true, 4, 'smile'),
  ('951063d0-8675-4235-ba46-929c8edf0a99', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'cooperation', 'Cooperation', 'Following instructions', 'How readily the child followed instructions.', '{"1":"Did not follow instructions","2":"Followed very few instructions, with full support","3":"Followed some instructions with repetition","4":"Followed most instructions with a reminder","5":"Followed instructions readily"}', 1, true, 5, 'handshake'),
  ('c66b779b-9d1d-48ba-9fe1-42ec442e353d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'independence', 'Independence (prompt level)', 'Doing it independently', 'The most common prompt level used in the session.', '{"1":"Full physical prompt","2":"Partial physical prompt","3":"Model or gestural prompt","4":"Verbal prompt","5":"Independent"}', 1, true, 6, 'footprints'),
  ('a48b0ddf-3b4b-4c85-bd99-6fb7c5be00a5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'communication', 'Communication / Interaction', 'Communication', 'Attempts to communicate in any mode: speech, sign, AAC, gesture.', '{"1":"No attempts","2":"Rare attempts, only with full prompting","3":"Some attempts when prompted","4":"Regular attempts, some spontaneous","5":"Frequent spontaneous attempts"}', 1, true, 7, 'message-circle'),
  ('24124777-0ef3-4cff-851d-5155af0ee7b5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'transitions', 'Transitions', 'Moving between activities', 'How the child managed changes between activities.', '{"1":"Major difficulty or meltdown at transitions","2":"Difficulty at most transitions","3":"Managed with support","4":"Managed with a warning or visual cue","5":"Smooth"}', 1, true, 8, 'repeat'),
