insert into public.goal_bank (id, organization_id, domain, therapy_type_key, staff_text, parent_text) values
  ('f6464ef9-52c4-4be2-a09e-17b634a6d71d', null, 'communication', 'speech', 'Requests desired items using 2-word phrases (e.g., ''want ball'') in 8/10 opportunities', 'Asks for things using two words, like ''want ball'''),
  ('609807d6-1368-43f1-ae30-d43eed3e9669', null, 'communication', 'speech', 'Responds to name by orienting/eye contact within 3 seconds in 4/5 opportunities', 'Looks up or turns when we call their name'),
  ('afe722b4-d9a7-4d61-9a9a-30849a58d241', null, 'communication', 'speech', 'Follows 1-step instructions without gestural cues in 80% of trials', 'Follows simple one-step instructions like ''give me the cup'''),
  ('6b776a96-3478-4e91-8e5e-677edb72d909', null, 'communication', 'speech', 'Answers ''what'' and ''where'' questions about a picture with 80% accuracy', 'Answers simple ''what'' and ''where'' questions about pictures'),
  ('de331eee-6b9b-4536-afc1-c73d05a4fd19', null, 'communication', 'speech', 'Initiates a PECS picture exchange to request across 3 settings', 'Hands over a picture card to ask for something'),
  ('8b6b615c-f75b-4889-8b2c-d0f466c6e279', null, 'communication', 'speech', 'Uses AAC device to request using core words (''more'', ''stop'', ''help'') spontaneously', 'Uses the talking device to say ''more'', ''stop'' or ''help'''),
  ('f519d3e3-733e-41aa-98ee-5f344b17e8b9', null, 'communication', 'speech', 'Uses greetings (''hi'', ''bye'', namaste) appropriately with familiar adults', 'Says hello and bye (or namaste) to people they know'),
  ('2843a9d4-19a7-4e43-847d-410e2c451351', null, 'communication', 'speech', 'Produces /s/ in initial position of words at word level with 80% accuracy', 'Says the ''s'' sound clearly at the start of words'),
  ('1043840c-3323-46e3-b0d6-78e6411d4011', null, 'communication', 'speech', 'Produces /k/ and /g/ in initial position at word level with 80% accuracy', 'Says ''k'' and ''g'' sounds clearly (like ''cat'' and ''go'')'),
  ('1ad31ef9-6755-4dad-86be-13c9a264b6d5', null, 'communication', 'speech', 'Uses 3–4 word sentences to describe actions in pictures', 'Talks in short sentences of 3–4 words'),
  ('b969ec61-cc57-4b89-8880-f88d7e567f8d', null, 'communication', 'speech', 'Demonstrates lip closure and tongue lateralisation during oral-motor exercises in 4/5 trials', 'Does mouth exercises that help with clearer speech and eating'),
  ('f0c74316-39f8-43b9-8bed-6d7ed2805ec1', null, 'communication', 'speech', 'Maintains a conversation for 3 turns on a familiar topic', 'Keeps a short back-and-forth chat going for 3 turns'),
  ('e8984226-a047-4582-9b64-cd9dafe2a9d1', null, 'communication', 'speech', 'Uses ''I/me'' correctly in requests instead of echoed ''you'' in 8/10 opportunities', 'Says ''I want…'' instead of ''you want…'''),
  ('3c82033f-2fd9-479c-91ca-c3a69bf01175', null, 'communication', 'audiology', 'Detects all Ling-6 sounds at 1 metre with implant in 5/5 trials', 'Notices and responds to everyday speech sounds with the device on'),
  ('5c88cafb-6dc2-4316-881d-ddccae29fc55', null, 'communication', 'audiology', 'Discriminates between 2-syllable words in a closed set of 4 with 80% accuracy', 'Tells apart similar-sounding words when listening'),
  ('2461847d-d345-4c7d-9e66-7f89fdbac5c5', null, 'self_care', 'audiology', 'Indicates when the hearing device is not working (dead battery/off)', 'Lets us know when the hearing device stops working'),
  ('7410717d-ca0f-46b3-997e-3ecf583d1efd', null, 'fine_motor', 'occupational', 'Picks up small objects (beads, peas) using a neat pincer grasp in 8/10 trials', 'Picks up small things with thumb and finger'),
  ('6126d95d-9f34-4a69-8ed2-c875003e8125', null, 'fine_motor', 'occupational', 'Snips paper with child-safe scissors with correct hand position, minimal assistance', 'Cuts paper with child-safe scissors'),
  ('48cc9796-72f4-44d9-9e60-be16a65027c9', null, 'fine_motor', 'occupational', 'Uses a functional tripod grasp on a crayon/pencil for 5 minutes', 'Holds a pencil the right way while drawing'),
  ('6ef426a4-bf63-40be-8460-c2eb457e59c9', null, 'fine_motor', 'occupational', 'Copies vertical line, horizontal line and circle', 'Copies lines and circles on paper'),
  ('6a92e7ef-64bc-41aa-8342-62e420a673f1', null, 'self_care', 'occupational', 'Fastens and unfastens 3 large buttons independently', 'Does up big buttons on their own'),
  ('573b4529-9cc5-4a4a-8397-54ea510c9a15', null, 'fine_motor', 'occupational', 'Writes own name legibly within lines', 'Writes own name neatly on the lines'),
  ('610289d8-d6b8-4203-9e95-1aeed0f32b19', null, 'gross_motor', 'physio', 'Climbs stairs with alternating feet using a rail', 'Goes up the stairs one foot per step, holding the railing'),
  ('cd4b9efe-3ee2-48a5-b2ad-c002625797b9', null, 'gross_motor', 'physio', 'Catches a medium ball from 2 metres with both hands', 'Catches a ball with both hands'),
  ('1ecf6c9e-444d-4937-bc6f-ecac6b5a8999', null, 'gross_motor', 'physio', 'Performs sit-to-stand from a small chair without hand support 5 times', 'Stands up from a small chair without using hands'),
  ('19d3f6dd-6090-4756-b78c-5bc2e9159f8d', null, 'gross_motor', 'physio', 'Walks 10 metres with a posterior walker with stand-by assistance', 'Walks across the room with the walker'),
  ('d661af01-9eb0-4eb9-9d67-4a657db0f465', null, 'gross_motor', 'occupational', 'Stands on one foot for 5 seconds each side', 'Balances on one foot for a few seconds'),
  ('2cbc6b17-56ca-4bf5-924f-430f649e8f0d', null, 'gross_motor', 'physio', 'Maintains head control in supported sitting for 2 minutes', 'Holds head up steadily while sitting with support'),
  ('d6e23778-d544-4568-ad71-90294363ea7d', null, 'self_care', 'occupational', 'Feeds self with a spoon with minimal spillage for a full meal', 'Eats with a spoon by themselves without much spilling'),
  ('86ed0c41-c7c0-4d65-a136-cb95a6fdb395', null, 'self_care', 'occupational', 'Completes 6-step handwashing sequence with a visual schedule', 'Washes hands by themselves using the picture steps'),
  ('78231ac9-65ba-4bc4-8a5d-e0542714511d', null, 'self_care', 'special_ed', 'Signals need for toilet (word/sign/picture) before accidents in 4/5 opportunities', 'Tells us when they need the toilet'),
  ('67ebd77d-97a9-4c46-b78e-bdcaffb65a21', null, 'self_care', 'occupational', 'Puts on a pull-over T-shirt independently', 'Puts on a T-shirt by themselves'),
  ('a46c6f7f-b85b-42db-8126-859d645fb01d', null, 'self_care', 'occupational', 'Opens tiffin box and water bottle independently at snack time', 'Opens their tiffin box and water bottle by themselves'),
  ('fae3d2da-19bf-4287-8e4e-f0c44e7f6809', null, 'social', 'behaviour', 'Takes turns in a structured 2-person game for 5 minutes', 'Takes turns in a simple game'),
  ('e3177e8b-58ee-47d1-85b0-e83b940f9a0d', null, 'social', 'speech', 'Follows a point to an object and shares attention (looks back to adult) in 4/5 trials', 'Looks where we point and shares the moment with us'),
  ('dea8cfbd-331a-4ddf-8641-6517623896cd', null, 'social', 'behaviour', 'Engages in parallel play next to a peer for 10 minutes', 'Plays happily next to another child'),
  ('056b3b9f-b404-4d13-8331-65d1ffcd47d5', null, 'social', 'special_ed', 'Shares materials with a peer when asked', 'Shares toys when asked'),
  ('4a05e095-bfbc-4f7c-94f3-098c88001315', null, 'behaviour', 'behaviour', 'Waits for a preferred item for up to 2 minutes using a visual timer without problem behaviour', 'Waits calmly for up to 2 minutes using the timer'),
  ('8cf5815f-1cac-4d8e-9873-0c84d7227725', null, 'behaviour', 'behaviour', 'Transitions between activities with a 2-minute warning and first-then board without protest in 80% of transitions', 'Moves from one activity to the next calmly when given a warning'),
  ('b4ef1840-4089-4573-a930-620e1fd6a3e9', null, 'behaviour', 'behaviour', 'Remains seated at the table for a 10-minute structured activity', 'Sits at the table for a 10-minute activity'),
  ('16357227-cb7f-4727-9dcf-3329c1c9a31d', null, 'behaviour', 'behaviour', 'Requests a break using a break card instead of eloping', 'Asks for a break (with a card) instead of running off'),
  ('a19fd52e-0f2e-433e-a9d8-54cd61ab971d', null, 'behaviour', 'behaviour', 'Uses ''calm hands'' strategy instead of hitting when frustrated, 4/5 opportunities', 'Keeps hands calm instead of hitting when upset'),
  ('6b981086-1847-422a-b03a-5735b23b94a1', null, 'behaviour', 'behaviour', 'Raises hand and waits to be called on in a small group', 'Puts hand up and waits for their turn to speak'),
  ('6944d431-4683-47a7-a956-520b8b3ebb15', null, 'cognition', 'special_ed', 'Matches 6 colours with 80% accuracy', 'Matches colours'),
  ('33cd236f-6bcd-41a9-95cd-5163335659ad', null, 'cognition', 'special_ed', 'Sorts pictures into 3 categories (animals, food, vehicles)', 'Sorts pictures into groups like animals and food'),
  ('350ef90f-c280-41a4-9274-1eaa18a1f87d', null, 'cognition', 'special_ed', 'Counts objects 1–10 with one-to-one correspondence', 'Counts up to 10 objects, touching each one'),
  ('f28d0269-f549-4c95-b985-48a9de02d11d', null, 'cognition', 'special_ed', 'Blends and reads CVC words (e.g., cat, pen) with 80% accuracy', 'Reads short three-letter words'),
  ('d9fd0e97-8b39-4bf9-9fe3-78f789adbe2d', null, 'cognition', 'special_ed', 'Reads a grade-2 level passage at 60 words per minute with fewer than 5 errors', 'Reads a short passage smoothly'),
  ('3ef5aeec-1cf6-4a37-aa09-8ed21cc48c91', null, 'cognition', 'special_ed', 'Identifies Hindi varnamala letters (क–ज्ञ) with 80% accuracy', 'Recognises Hindi letters'),
  ('949a3b34-0fd8-4e25-a151-e2843853dad9', null, 'cognition', 'special_ed', 'Identifies coins and notes up to ₹100', 'Recognises coins and notes up to ₹100'),
  ('9fcdd18f-07c0-4c35-87b3-40aba6683865', null, 'cognition', 'special_ed', 'Completes a 10-minute worksheet with no more than 2 prompts', 'Finishes a short worksheet with little help'),
  ('17ca4fe6-6b90-4859-8f40-268619df3ae9', null, 'sensory', 'occupational', 'Tolerates messy play (sand, dough) for 5 minutes without distress', 'Plays with sand or dough for 5 minutes without getting upset'),
  ('0f9c4bdd-2fe6-422f-af3e-ee3f90c37235', null, 'sensory', 'occupational', 'Uses a sensory strategy (deep pressure, fidget) to self-regulate when prompted by a visual cue', 'Uses calming tools like a squeeze ball when feeling overwhelmed'),
  ('38f43a0d-16d5-4265-8f09-34b14a3e5a35', null, 'sensory', 'occupational', 'Remains regulated in a noisy room (assembly) for 10 minutes with ear defenders', 'Stays calm in noisy places with ear muffs on'),
  ('1bb01ad2-7e92-4819-ad97-5cca61c47f19', null, 'sensory', 'occupational', 'Accepts 3 new food textures at snack time', 'Tries new foods with different textures')
