insert into public.profile_edits (id, organization_id, child_id, field, old_value, new_value, "by", at, created_at) values
  ('d38fb9e0-8d3c-4d2d-bdb6-53a4395e8009', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', 'dos', 'Give a 2-minute warning and show the timer before every transition | Offer a choice of two (''bubbles or ball?'') instead of open questions | Keep instructions to 3–4 words and wait 5 seconds before repeating', 'Give a 2-minute warning and show the timer before every transition | Offer a choice of two (''bubbles or ball?'') instead of open questions | Keep instructions to 3–4 words and wait 5 seconds before repeating | Start with 5 minutes on the swing or trampoline — he settles faster after movement', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', '2026-10-27T12:15:00.000Z', '2026-10-27T12:15:00.000Z'),
  ('5538b18f-d6fd-4b12-af40-c084824f6079', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', 'triggers', 'loud_sounds | transitions | waiting', 'loud_sounds | transitions | waiting | change_in_routine | Pressure-cooker whistle', '68e54617-51f3-4b9b-ab2c-db49b3665be5', '2026-10-06T07:40:00.000Z', '2026-10-06T07:40:00.000Z'),
  ('3f1116cb-1a6c-432f-af81-6bb11ee79e5d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', 'calmingNotes', 'Firm squeezes on the shoulders, then count 1–10.', 'Firm squeezes on the shoulders (ask first), then count 1–10 slowly. Humming ''Twinkle Twinkle'' with him settles him in 2–3 minutes.', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', '2026-09-18T10:35:00.000Z', '2026-09-18T10:35:00.000Z')
