insert into public.resource_shares (id, organization_id, resource_id, child_id, user_id, shared_by, note, at, created_at, created_by) values
  ('f388745f-32c7-4a90-9150-dd5acacf9cf5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '62b0a54d-305d-4e8a-bc6b-016e708167e1', 'c8639db6-6c54-4c04-9ed1-4e7febe6d7ed', null, '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Please stick this on the fridge and use 2–3 words a day.', '2026-10-17T11:40:00.000Z', '2026-10-17T11:40:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('362937a2-d2a9-43e3-95df-8cd00971eac1', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '1df1915b-81c9-484c-9731-4282484d38c1', 'b4e9f8a3-0ce6-49d7-af2a-17d92f2e8005', null, '580a7543-d6f2-475c-a235-255657dba3f5', 'Heavy-work ideas on page 2 work really well for Arnav.', '2026-10-17T11:40:00.000Z', '2026-10-17T11:40:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('cc5af901-89d1-4ca1-b63a-993d8f1b73f5', '4af0f750-d9c2-4240-8024-206161c10975', '1f91a1ca-d16f-4540-944c-490b06249d11', '7bfcf594-d3b5-4b80-b79b-b2397c6b839d', null, 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'This is the snack-time routine we use in session.', '2026-10-17T11:40:00.000Z', '2026-10-17T11:40:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('f7c6e75c-4a60-431b-a6d6-f2b626f36119', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'b96f203d-3c9a-40e3-bc1c-cf7378731b9d', '515a4c47-4c1b-455c-baed-21c6c9462f75', null, '580a7543-d6f2-475c-a235-255657dba3f5', 'Start with the 2-hourly routine on page 3.', '2026-10-17T11:40:00.000Z', '2026-10-17T11:40:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('b199e2e9-ffa3-408f-b5c4-eb2bbfcad1e5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '73c6a76f-e666-4736-ad1b-1c5835ade425', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', null, '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'This is exactly what we do in session — pause and wait 5 seconds.', '2026-10-17T11:40:00.000Z', '2026-10-17T11:40:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d')
insert into public.home_tasks (id, organization_id, child_id, goal_id, assigned_by, title, steps, frequency_per_week, duration_minutes, resource_id, demo_media_id, active_from, active_to, status, created_at, created_by) values
  ('1861e23c-7394-4590-afbf-b1c5c220671d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', '88b4a602-61d3-40cf-b2e3-d6501b0c3c01', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Bubble time: ask with two words', '["Sit face to face and blow bubbles 2–3 times.","Stop and wait. Hold the wand near your face.","Wait 5 seconds for ''more bubbles'' or ''blow bubbles''.","If no words, say it for them once, then wait again.","Give bubbles right away for any 2-word try."]', 5, 10, null, null, '2026-10-06', '2026-11-08', 'active', '2026-10-06T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('3ed96810-c5a5-40ac-83ee-35e1b6aae645', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', '7a8b3690-5b33-4f1a-b715-08bb5cc28cc9', '580a7543-d6f2-475c-a235-255657dba3f5', 'Rajma bean posting', '["Put 10 rajma beans in a bowl.","Show how to pick one with thumb and first finger.","Post each bean into a bottle with a small opening.","Count together as they drop in."]', 5, 10, null, null, '2026-10-06', '2026-11-20', 'active', '2026-10-06T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('c9e79956-355a-4774-b13d-3467e2903aa9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'd72ba1e4-4bbd-4a55-88f6-963c125c3dc1', '446660be-2128-4461-8380-eb9adbc14c11', '68e54617-51f3-4b9b-ab2c-db49b3665be5', 'Waiting with the timer', '["Show the favourite item and say ''wait''.","Start the sand timer (start with 30 seconds).","Give the item the moment the timer ends.","Add 15 seconds every few days."]', 5, 10, null, null, '2026-10-03', '2026-11-24', 'active', '2026-10-03T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('2a281c08-60d1-43ec-b5f4-d37d54bee95d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '62f9d66f-f535-423f-a3ea-4d89b5d919ad', '26254a7a-0799-4820-aeef-67a30ee2d0d1', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', '''K'' and ''G'' throat sounds', '["Lie back on a pillow and say ''k-k-k'' like a ticking clock.","Sit up and say: cat, car, cup, go, gate.","If it comes out as ''t'', smile and say the word back slowly.","Five words is enough — end with a sticker."]', 5, 5, null, null, '2026-10-03', '2026-11-08', 'active', '2026-10-03T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('2b95feda-ba23-4d94-98c3-0d970bd8c911', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '62f9d66f-f535-423f-a3ea-4d89b5d919ad', 'bca66f87-037d-48d0-b4f7-6bb22762d399', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Tell me the story', '["Look at family photos or a picture book.","Ask ''What is Papa doing?''","Expand their answer: ''eating'' → ''Papa is eating roti''.","Let them say it back; praise every try."]', 4, 10, null, null, '2026-10-03', '2026-11-15', 'active', '2026-10-03T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('c633b751-15e7-4e18-ae43-00e01c9647e5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '8d37b4cf-781c-4ab3-8e98-3171d3ea8c0d', '4d50d2b1-b4e7-42a9-bd12-d3b5b703d8fd', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Hello and bye practice', '["When someone comes home, stop at the door together.","Model ''Hi!'' or ''Namaste'' with a wave.","Wait for them to copy.","Do the same when someone leaves."]', 5, 5, null, null, '2026-10-04', '2026-11-25', 'active', '2026-10-04T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('72935c14-9cb9-4cf8-8f2a-e5157add90d9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '8d37b4cf-781c-4ab3-8e98-3171d3ea8c0d', '5776ea85-3850-482d-96f6-18454828adfd', '580a7543-d6f2-475c-a235-255657dba3f5', 'Button practice with Papa’s shirt', '["Lay a big-button shirt flat on the bed.","Push the button halfway, they pull it through.","Next time, let them do both steps.","Then try on their own school shirt."]', 5, 10, null, null, '2026-10-07', '2026-11-15', 'active', '2026-10-07T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('eee3bad0-01d0-40e0-ba53-3d49e6c56fcd', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '8d37b4cf-781c-4ab3-8e98-3171d3ea8c0d', '1dc04a61-be4a-4f27-adfe-a36f8730e60d', '68e54617-51f3-4b9b-ab2c-db49b3665be5', 'Counting rotis and spoons', '["Ask them to count spoons while setting the table.","Touch each spoon while counting.","Count steps on the stairs too.","Go up to 10."]', 5, 5, null, null, '2026-10-02', '2026-11-28', 'active', '2026-10-02T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('c765dc0d-ba7d-4250-be2b-a924f31050b1', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'c8639db6-6c54-4c04-9ed1-4e7febe6d7ed', '9263c4d9-bd58-4c32-86e2-d3eab24ab081', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Picture card at snack time', '["Keep the snack picture card on the table.","Hold the snack where they can see it.","Wait for them to pick up the card and give it to you.","Say the word (''biscuit!'') and give the snack straight away."]', 6, 10, null, null, '2026-10-03', '2026-11-25', 'active', '2026-10-03T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('c184cd21-f521-4334-ba7f-46d0ae1e385d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'c8639db6-6c54-4c04-9ed1-4e7febe6d7ed', 'f826742f-fd4f-4733-9f48-634968d9962d', '580a7543-d6f2-475c-a235-255657dba3f5', 'Atta dough play', '["Make soft atta dough together.","Start by poking it with a spoon, then one finger.","Hide a small toy inside to find.","Wipe hands whenever they ask."]', 4, 10, null, null, '2026-10-07', '2026-11-09', 'active', '2026-10-07T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('73add1e4-0bb4-4d74-8f2c-f351306a0d19', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'c8639db6-6c54-4c04-9ed1-4e7febe6d7ed', 'b5343073-95c3-4600-ba07-7e9e8aa06ee5', '580a7543-d6f2-475c-a235-255657dba3f5', 'Spoon at lunch', '["Use a bowl with a high edge and a thick-handled spoon.","Start with thick foods: khichdi, curd rice.","Help only at the wrist, not the hand.","Let them finish the last 5 spoons alone."]', 7, 15, null, null, '2026-10-04', '2026-11-08', 'active', '2026-10-04T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('263d9cc7-03b8-4c5c-86d9-912a4580b93d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ff30ba43-ec69-4e19-a7a0-f09f9c04c845', '17a79b23-33b1-451a-821d-5a3cac1bebc9', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Mouth exercises before meals', '["Sit upright with feet supported.","Blow a cotton ball across the table 5 times.","Lick honey from the corners of the lips, left and right.","Hold a straw between the lips for 5 seconds."]', 6, 5, null, null, '2026-10-06', '2026-11-24', 'active', '2026-10-06T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('85a90882-8ed0-4f30-8483-228b741ac319', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ff30ba43-ec69-4e19-a7a0-f09f9c04c845', '3c54d750-d2b8-4588-8d8e-4a35e5ae9ff1', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Dinner-table chat', '["Pick one topic they love (cricket, school bus).","Ask one question and wait.","Answer with a short comment and a question back.","Count the turns together with fingers — aim for 3."]', 5, 5, null, null, '2026-10-01', '2026-11-23', 'active', '2026-10-01T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('28a5d4dc-d739-4160-a2e4-b1d9093cd4c9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ff30ba43-ec69-4e19-a7a0-f09f9c04c845', 'b0392f95-9550-4a7f-8604-c6e39d9f2aad', '580a7543-d6f2-475c-a235-255657dba3f5', 'Button practice with Papa’s shirt', '["Lay a big-button shirt flat on the bed.","Push the button halfway, they pull it through.","Next time, let them do both steps.","Then try on their own school shirt."]', 5, 10, null, null, '2026-10-08', '2026-11-19', 'active', '2026-10-08T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('42046b9c-21a3-412c-b477-cb852ffc46dd', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ee78e19f-f67d-4f36-a7a6-ff68240d7b45', '5d441273-08a2-42a0-9ffe-58aa8b337c3d', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Listening picture game', '["Put 4 picture cards on the table.","Cover your mouth with a paper and say one word.","They point to the matching picture.","Switch off the fan and TV while playing."]', 4, 10, null, null, '2026-10-01', '2026-11-28', 'active', '2026-10-01T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('e3c60859-caca-4378-9610-db2cff6e34c1', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ee78e19f-f67d-4f36-a7a6-ff68240d7b45', '1d10c61e-2a16-4bc3-9ef2-7a44bbff41d1', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Dinner-table chat', '["Pick one topic they love (cricket, school bus).","Ask one question and wait.","Answer with a short comment and a question back.","Count the turns together with fingers — aim for 3."]', 5, 5, null, null, '2026-10-06', '2026-11-20', 'active', '2026-10-06T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('1bd4c032-0e45-4e5c-a3b6-ffbfaba8f639', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'ee78e19f-f67d-4f36-a7a6-ff68240d7b45', '203836f5-3b6f-40df-ba8b-2f3b5ff9bf55', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Device check together', '["Let them switch the device on by themselves.","Ask: \"Can you hear me well?\"","Practise saying \"my battery is finished\" when it beeps.","Praise them for telling you."]', 5, 5, null, null, '2026-10-03', '2026-11-25', 'active', '2026-10-03T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('59312a7b-a1bf-4e4c-8284-22ce74e08649', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '515a4c47-4c1b-455c-baed-21c6c9462f75', '611fed68-f369-4739-b29b-5994eaa69e91', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Helper at home', '["Give one short instruction: ''Bring your shoes''.","Don''t point — just say it once.","Wait 5 seconds, then show if needed.","Praise: ''You brought your shoes!''"]', 5, 10, null, null, '2026-10-01', '2026-11-20', 'active', '2026-10-01T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('3bbaf7af-3839-4cbc-abea-2e2a23a23c39', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '515a4c47-4c1b-455c-baed-21c6c9462f75', '341fa41d-d174-4391-88d3-ae71ab2eda15', '580a7543-d6f2-475c-a235-255657dba3f5', 'Handwash with the picture chart', '["Stick the 6-step picture chart near the basin.","Point to each picture before they do the step.","Point less each day.","Clap when all 6 steps are done."]', 7, 5, null, null, '2026-10-02', '2026-11-24', 'active', '2026-10-02T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('2b053a55-a9e4-4a58-aad6-3600b759b5bd', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '515a4c47-4c1b-455c-baed-21c6c9462f75', 'e58f5cf8-3df6-41f6-81cf-b04fb90b5139', '580a7543-d6f2-475c-a235-255657dba3f5', 'Rangoli lines', '["Draw a line or circle on paper.","They copy it next to yours.","Try in a tray of atta (flour) with a finger too.","Three shapes a day is enough."]', 4, 10, null, null, '2026-10-02', '2026-11-24', 'active', '2026-10-02T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('69058cdd-b22e-4f20-8126-0194220dd44d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '74c68120-be71-4746-80b7-814fa0481011', 'c382231b-250d-424c-a4fe-e9b659a1ea7d', '68e54617-51f3-4b9b-ab2c-db49b3665be5', 'Hand-up game at dinner', '["Everyone at dinner raises a hand to talk.","Call on them after a 3-second wait.","Give a point for each good wait.","5 points = choose the bedtime story."]', 5, 5, null, null, '2026-09-30', '2026-11-15', 'active', '2026-09-30T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('319227a1-c3fe-44b4-90c2-6ab8228fc2a1', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '74c68120-be71-4746-80b7-814fa0481011', '2bc35c29-cce4-4691-bbe1-bd854671a955', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d', 'Dinner-table chat', '["Pick one topic they love (cricket, school bus).","Ask one question and wait.","Answer with a short comment and a question back.","Count the turns together with fingers — aim for 3."]', 5, 5, null, null, '2026-10-03', '2026-11-10', 'active', '2026-10-03T11:00:00.000Z', '8e94c13e-ee62-4ad4-8a50-2e27fce9bd4d'),
  ('010eca65-7736-405c-9f1e-b6a0df374d45', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '74c68120-be71-4746-80b7-814fa0481011', '61f71394-1c51-4199-bb2b-c0fc67e99a79', '68e54617-51f3-4b9b-ab2c-db49b3665be5', '10-minute worksheet', '["Clear the table except the worksheet and pencil.","Set a 10-minute timer.","Give at most 2 reminders.","Tick it together and give a token."]', 5, 10, null, null, '2026-10-03', '2026-11-17', 'active', '2026-10-03T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('777c978c-8482-4c7c-a710-ec85716a8285', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '62a9cd05-3ad3-4c0a-b0cc-9e3672ad3009', '87412600-5e5c-4840-8c18-ba09603a020d', '934479b0-7350-4029-9b97-4588c53d36d1', '''I want'' at snack time', '["Hold the snack and wait.","If they say ''you want juice?'', whisper ''I want juice''.","Wait for them to copy the right words.","Give the snack straight away when they say it."]', 6, 5, null, null, '2026-10-04', '2026-11-11', 'active', '2026-10-04T11:00:00.000Z', '934479b0-7350-4029-9b97-4588c53d36d1'),
  ('cad93d82-f0c7-46bc-9c96-ae678f20c02d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '62a9cd05-3ad3-4c0a-b0cc-9e3672ad3009', 'c421098c-1912-4a41-a474-c38cdc965b81', '68e54617-51f3-4b9b-ab2c-db49b3665be5', '''My turn, your turn'' ball rolling', '["Sit on the floor opposite each other.","Say ''my turn'' and roll the ball.","Say ''your turn'' and wait for them to roll it back.","Play for 5 minutes, then let them choose a game."]', 5, 10, null, null, '2026-10-02', '2026-11-24', 'active', '2026-10-02T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('c8310c65-0d8c-4ea8-b458-1db413cf0ee9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '676759b6-e854-4d15-9afb-42b6047d7c99', 'da2f02d7-cf91-46b6-ab9a-be9c605725b1', '934479b0-7350-4029-9b97-4588c53d36d1', 'Talking device: ''more'' and ''stop''', '["Keep the device open on the core page.","During play, press ''more'' yourself to show how.","Pause the play and wait for them to press ''more''.","Respond at once to every press, even by accident."]', 5, 10, null, null, '2026-10-04', '2026-11-14', 'active', '2026-10-04T11:00:00.000Z', '934479b0-7350-4029-9b97-4588c53d36d1'),
  ('ea1f7906-2ce1-4dec-9004-e1c3aaac889d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '676759b6-e854-4d15-9afb-42b6047d7c99', '867d540c-90ab-408a-ab2b-774748774ba9', '68e54617-51f3-4b9b-ab2c-db49b3665be5', 'Break card practice', '["Keep the green break card on the table.","At early signs (whining, flapping), point to it.","When they hand it over, allow 2 minutes of break.","Then return to the task calmly."]', 5, 5, null, null, '2026-10-03', '2026-11-09', 'active', '2026-10-03T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('d55d1a6e-3b7c-4fe8-9aac-90e7698cff15', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '676759b6-e854-4d15-9afb-42b6047d7c99', 'e99271d2-45d1-40ce-af95-cb0997c134b1', '580a7543-d6f2-475c-a235-255657dba3f5', 'Calm-down corner', '["Set up a corner with a cushion, squeeze ball and blanket.","Visit it once a day when calm, to practise.","When upset, show the calm-corner picture.","Stay close and quiet; praise when calm."]', 5, 10, null, null, '2026-10-03', '2026-11-09', 'active', '2026-10-03T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('8ca55b27-9f6d-4258-a95a-f40eea37444d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '79186a5c-4056-4810-a322-ae11c0a02b89', 'a2fd1950-d4fe-496b-954a-379608380271', '934479b0-7350-4029-9b97-4588c53d36d1', 'Paired reading', '["Use the coloured overlay and the reader from school.","Read one line together, then they read it alone.","Don''t correct every mistake — just reread the line.","End with a story they choose."]', 5, 10, null, null, '2026-10-05', '2026-11-18', 'active', '2026-10-05T11:00:00.000Z', '934479b0-7350-4029-9b97-4588c53d36d1'),
  ('44273c9d-b1af-4cc4-af87-7b00ee6e6b6d', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '79186a5c-4056-4810-a322-ae11c0a02b89', 'd79096cf-744e-4717-a702-8f61b069455d', '934479b0-7350-4029-9b97-4588c53d36d1', 'Shopkeeper game', '["Set up a pretend shop with price tags (₹5, ₹10, ₹20).","They pay with real coins and notes.","Ask them to name each one.","Swap: they become the shopkeeper."]', 3, 15, null, null, '2026-10-05', '2026-11-26', 'active', '2026-10-05T11:00:00.000Z', '934479b0-7350-4029-9b97-4588c53d36d1'),
  ('e4e55959-a258-450c-bdac-e25cd108e785', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', '79186a5c-4056-4810-a322-ae11c0a02b89', 'afb37ed8-3e87-43de-8bf3-c7e7ad1a8a49', '580a7543-d6f2-475c-a235-255657dba3f5', 'Name writing on 4-line notebook', '["Use the 4-line notebook from school.","Trace the name once with a finger.","Write the name 3 times.","Circle the neatest one together."]', 5, 10, null, null, '2026-10-06', '2026-11-15', 'active', '2026-10-06T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('b1adc2c0-85b5-4ae0-a742-4209d00bcba9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'b4e9f8a3-0ce6-49d7-af2a-17d92f2e8005', 'f3257710-fc84-4896-ba82-95ab90d727e9', '580a7543-d6f2-475c-a235-255657dba3f5', 'Small crayon colouring', '["Break crayons into small pieces (this helps the grip).","Colour a simple picture for 5 minutes.","Gently fix the grip if the fist comes back.","Put the picture up on the fridge!"]', 5, 10, null, null, '2026-10-04', '2026-11-18', 'active', '2026-10-04T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('0cfd7bc7-ba44-46ec-925e-c5e6184f1229', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'b4e9f8a3-0ce6-49d7-af2a-17d92f2e8005', '1263434e-fb3d-48c8-adbe-97df1a78ea0d', '68e54617-51f3-4b9b-ab2c-db49b3665be5', 'Table time', '["Choose an activity they like (puzzle, clay).","Set a timer for 5 minutes, then 7, then 10.","Give a token every 2 minutes of sitting.","5 tokens = a short swing or video."]', 5, 10, null, null, '2026-10-06', '2026-11-25', 'active', '2026-10-06T11:00:00.000Z', '68e54617-51f3-4b9b-ab2c-db49b3665be5'),
  ('51ffc759-1708-4860-b68e-4d74492935ed', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'b4e9f8a3-0ce6-49d7-af2a-17d92f2e8005', '3892830b-94f5-4468-a364-f136c1047269', '580a7543-d6f2-475c-a235-255657dba3f5', 'Flamingo game', '["Stand near a wall for support.","Lift one foot and count to 5 together.","Switch feet.","Three turns each side."]', 5, 5, null, null, '2026-10-08', '2026-11-27', 'active', '2026-10-08T11:00:00.000Z', '580a7543-d6f2-475c-a235-255657dba3f5'),
  ('443b5d31-51bf-4dac-ba9a-10c0e33a8759', '4af0f750-d9c2-4240-8024-206161c10975', '5a791f44-523f-4f09-a0d4-15909bc71a29', 'e946750e-80de-456b-9fa2-4a4cfb9c0149', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Bubble time: ask with two words', '["Sit face to face and blow bubbles 2–3 times.","Stop and wait. Hold the wand near your face.","Wait 5 seconds for ''more bubbles'' or ''blow bubbles''.","If no words, say it for them once, then wait again.","Give bubbles right away for any 2-word try."]', 5, 10, null, null, '2026-09-29', '2026-11-19', 'active', '2026-09-29T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('122c08c6-abdd-4f5c-a462-99bb52cd91e1', '4af0f750-d9c2-4240-8024-206161c10975', '5a791f44-523f-4f09-a0d4-15909bc71a29', 'bb095f7c-1345-4163-8764-a65e2244e5f1', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'First-then board at home', '["Before switching, show the first-then pictures.","Say ''2 more minutes'' and show the timer.","When it rings: ''Finished TV, then bath''.","Praise the calm switch right away."]', 7, 5, null, null, '2026-10-06', '2026-11-26', 'active', '2026-10-06T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('d429d1dc-574f-43b0-8cfd-52e548ba48dd', '4af0f750-d9c2-4240-8024-206161c10975', '5a791f44-523f-4f09-a0d4-15909bc71a29', 'a393952c-e2ff-477c-9f33-52118a519131', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Snip the paper strips', '["Cut old newspaper into thin strips.","Thumb on top: ''thumbs up'' scissors.","Snip the strips into small pieces.","Stick the pieces on paper to make a picture."]', 4, 10, null, null, '2026-09-30', '2026-11-21', 'active', '2026-09-30T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('9842b040-43f3-4734-a1fc-89356070b8bd', '4af0f750-d9c2-4240-8024-206161c10975', '6f59633c-873e-42ba-9d10-1d57b6ff053d', '24381233-84aa-4abd-ac41-79432c8f4a7d', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Helper at home', '["Give one short instruction: ''Bring your shoes''.","Don''t point — just say it once.","Wait 5 seconds, then show if needed.","Praise: ''You brought your shoes!''"]', 5, 10, null, null, '2026-10-01', '2026-11-19', 'active', '2026-10-01T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('b1f5db9d-7be0-4bc4-8bf6-f7fc078fc6a1', '4af0f750-d9c2-4240-8024-206161c10975', '6f59633c-873e-42ba-9d10-1d57b6ff053d', '6a234d9f-f59a-4e47-acea-ed392a545175', '42fb9326-d966-4c8e-94ca-4e55da47fbe9', 'Stair climbing practice', '["Use the building stairs with the railing.","Say ''one foot, next step'' for each step.","Do one flight up and down, twice.","Stay one step below for safety."]', 5, 10, null, null, '2026-09-30', '2026-11-13', 'active', '2026-09-30T11:00:00.000Z', '42fb9326-d966-4c8e-94ca-4e55da47fbe9'),
  ('e0e34bed-ac30-4cb0-890f-a3609d08a395', '4af0f750-d9c2-4240-8024-206161c10975', '6f59633c-873e-42ba-9d10-1d57b6ff053d', '9274d531-1e82-4d2e-9e26-db622119f75d', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Spoon at lunch', '["Use a bowl with a high edge and a thick-handled spoon.","Start with thick foods: khichdi, curd rice.","Help only at the wrist, not the hand.","Let them finish the last 5 spoons alone."]', 7, 15, null, null, '2026-09-29', '2026-11-15', 'active', '2026-09-29T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('8b66a6b1-06ec-4920-993f-c8c0a1451c59', '4af0f750-d9c2-4240-8024-206161c10975', '0e1decb4-a81e-4b96-841b-dd373c9ee45d', '8806c122-a761-40f5-9e82-30a21db076f9', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Tell me the story', '["Look at family photos or a picture book.","Ask ''What is Papa doing?''","Expand their answer: ''eating'' → ''Papa is eating roti''.","Let them say it back; praise every try."]', 4, 10, null, null, '2026-10-08', '2026-11-10', 'active', '2026-10-08T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('828d99f9-e9c6-4b20-82d6-3e1c0a36675d', '4af0f750-d9c2-4240-8024-206161c10975', '0e1decb4-a81e-4b96-841b-dd373c9ee45d', 'ce6eee22-95ad-4a8e-ae37-c2f1db582545', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'Counting rotis and spoons', '["Ask them to count spoons while setting the table.","Touch each spoon while counting.","Count steps on the stairs too.","Go up to 10."]', 5, 5, null, null, '2026-10-03', '2026-11-09', 'active', '2026-10-03T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('36ff8235-81bf-4154-aebc-c3f410f1b0cd', '4af0f750-d9c2-4240-8024-206161c10975', 'cd15d906-2b9e-4141-920d-07fed91e4cd1', '293dccb2-36e3-4bec-ac59-86cf9e09dda1', '42fb9326-d966-4c8e-94ca-4e55da47fbe9', 'Flamingo game', '["Stand near a wall for support.","Lift one foot and count to 5 together.","Switch feet.","Three turns each side."]', 5, 5, null, null, '2026-10-02', '2026-11-21', 'active', '2026-10-02T11:00:00.000Z', '42fb9326-d966-4c8e-94ca-4e55da47fbe9'),
  ('b6d835f9-ac21-4c18-a382-2dd0db01fa35', '4af0f750-d9c2-4240-8024-206161c10975', 'cd15d906-2b9e-4141-920d-07fed91e4cd1', '3042465a-5c10-443f-a985-8d48f362e0b9', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Button practice with Papa’s shirt', '["Lay a big-button shirt flat on the bed.","Push the button halfway, they pull it through.","Next time, let them do both steps.","Then try on their own school shirt."]', 5, 10, null, null, '2026-09-29', '2026-11-25', 'active', '2026-09-29T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('632cf8bf-17d2-4cc4-8c0c-446e8e7f1c51', '4af0f750-d9c2-4240-8024-206161c10975', 'cd15d906-2b9e-4141-920d-07fed91e4cd1', 'af5c0130-35be-4843-b29e-23566780c2c1', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'T-shirt on by myself', '["Lay the T-shirt face down, tag at the top.","Head first, then one arm, then the other.","Help with the first step only.","Use a loose T-shirt for practice."]', 5, 5, null, null, '2026-10-03', '2026-11-17', 'active', '2026-10-03T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('4bebb3c3-b771-47ec-8b61-b4faacb383bd', '4af0f750-d9c2-4240-8024-206161c10975', '06e5137d-9a10-4593-a795-5e93df2274d5', '581c4504-9db3-4606-a58a-8edb26e9ab55', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'Shopkeeper game', '["Set up a pretend shop with price tags (₹5, ₹10, ₹20).","They pay with real coins and notes.","Ask them to name each one.","Swap: they become the shopkeeper."]', 3, 15, null, null, '2026-10-08', '2026-11-27', 'active', '2026-10-08T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('e43d5a90-5160-44a0-9342-4105a1aeb63d', '4af0f750-d9c2-4240-8024-206161c10975', '06e5137d-9a10-4593-a795-5e93df2274d5', '5145d919-83e1-491d-a69e-fdf55e2838bd', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Name writing on 4-line notebook', '["Use the 4-line notebook from school.","Trace the name once with a finger.","Write the name 3 times.","Circle the neatest one together."]', 5, 10, null, null, '2026-10-03', '2026-11-15', 'active', '2026-10-03T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('1f5c1a8b-fd9e-4940-ba75-59da4284cd61', '4af0f750-d9c2-4240-8024-206161c10975', '162445c5-e220-4550-b080-f1f0ea76a949', '7c1b7341-2f26-4bb6-8f98-922617aaa9f9', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Listening picture game', '["Put 4 picture cards on the table.","Cover your mouth with a paper and say one word.","They point to the matching picture.","Switch off the fan and TV while playing."]', 4, 10, null, null, '2026-10-08', '2026-11-19', 'active', '2026-10-08T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('9c0b2d75-3b91-48ec-ada2-68e01125a4c1', '4af0f750-d9c2-4240-8024-206161c10975', '162445c5-e220-4550-b080-f1f0ea76a949', '8ac85c4a-dde8-479f-8136-f990c210f519', 'c92376df-53dc-440e-8268-fcf0c8dc2011', '''S'' snake sound game', '["Make a long ''ssss'' snake sound together in the mirror.","Say 5 picture words: sun, sock, soap, sit, seven.","Praise good tries; repeat a word only twice.","Stop while it is still fun."]', 5, 5, null, null, '2026-10-01', '2026-11-09', 'active', '2026-10-01T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('aa4c6e2c-4b91-4aa0-b90e-4311d05e27d5', '4af0f750-d9c2-4240-8024-206161c10975', '162445c5-e220-4550-b080-f1f0ea76a949', '7c8a77ad-6235-498c-be69-a404548b4c29', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Morning listening check', '["Check the device is on and the battery light is fine.","Stand behind them and say: m, oo, ee, ah, sh, s.","They raise a hand each time they hear a sound.","Tell the therapist if any sound is missed two days in a row."]', 6, 5, null, null, '2026-10-01', '2026-11-28', 'active', '2026-10-01T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('cdd23b5c-8978-463c-8dd4-88419e151601', '4af0f750-d9c2-4240-8024-206161c10975', '7bfcf594-d3b5-4b80-b79b-b2397c6b839d', '9e5c32af-2327-4236-aaa9-3b7ca73244d9', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Picture card at snack time', '["Keep the snack picture card on the table.","Hold the snack where they can see it.","Wait for them to pick up the card and give it to you.","Say the word (''biscuit!'') and give the snack straight away."]', 6, 10, null, null, '2026-10-01', '2026-11-16', 'active', '2026-10-01T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('44244779-66f7-4808-bb65-f6ec06b83cd9', '4af0f750-d9c2-4240-8024-206161c10975', '7bfcf594-d3b5-4b80-b79b-b2397c6b839d', '14d2938f-bc72-4e9d-ba18-1787104148ed', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'Table time', '["Choose an activity they like (puzzle, clay).","Set a timer for 5 minutes, then 7, then 10.","Give a token every 2 minutes of sitting.","5 tokens = a short swing or video."]', 5, 10, null, null, '2026-09-29', '2026-11-18', 'active', '2026-09-29T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('12dceff5-95ef-4b60-a031-2c3caf44fe75', '4af0f750-d9c2-4240-8024-206161c10975', '7bfcf594-d3b5-4b80-b79b-b2397c6b839d', '9e727095-3d40-4e2f-887b-e2cf621431cd', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Atta dough play', '["Make soft atta dough together.","Start by poking it with a spoon, then one finger.","Hide a small toy inside to find.","Wipe hands whenever they ask."]', 4, 10, null, null, '2026-10-02', '2026-11-10', 'active', '2026-10-02T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('2e8fa4db-7f2d-4540-bf04-362af783f2f9', '4af0f750-d9c2-4240-8024-206161c10975', 'fe154d4a-1569-4307-9003-d1a0991c2e91', '56288f7f-6731-415b-9e54-80e5d5216025', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'Hand-up game at dinner', '["Everyone at dinner raises a hand to talk.","Call on them after a 3-second wait.","Give a point for each good wait.","5 points = choose the bedtime story."]', 5, 5, null, null, '2026-10-02', '2026-11-19', 'active', '2026-10-02T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('ac32f6c4-5882-4fa0-b37d-5671f83b5805', '4af0f750-d9c2-4240-8024-206161c10975', 'fe154d4a-1569-4307-9003-d1a0991c2e91', 'be0177bd-8067-4a18-b5e9-b66c9d94320d', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Small crayon colouring', '["Break crayons into small pieces (this helps the grip).","Colour a simple picture for 5 minutes.","Gently fix the grip if the fist comes back.","Put the picture up on the fridge!"]', 5, 10, null, null, '2026-09-30', '2026-11-15', 'active', '2026-09-30T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('f0678d59-f275-4d58-98ba-ec189dc60689', '4af0f750-d9c2-4240-8024-206161c10975', '7fd6b441-a0ff-4af8-ad3c-922c04ca07e1', '8eed3681-19e6-426d-91f4-eaf93f5ffc95', '42fb9326-d966-4c8e-94ca-4e55da47fbe9', 'Sitting and looking up', '["Sit them in the corner chair with support.","Hold a favourite toy at eye level.","Move it slowly side to side.","Count to 60, rest, then once more."]', 6, 5, null, null, '2026-10-01', '2026-11-28', 'active', '2026-10-01T11:00:00.000Z', '42fb9326-d966-4c8e-94ca-4e55da47fbe9'),
  ('d95b7b93-4990-4740-a3d5-146ec357d621', '4af0f750-d9c2-4240-8024-206161c10975', '7fd6b441-a0ff-4af8-ad3c-922c04ca07e1', 'ff0a7226-bd2a-4bb9-8943-2b2e36285b59', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Talking device: ''more'' and ''stop''', '["Keep the device open on the core page.","During play, press ''more'' yourself to show how.","Pause the play and wait for them to press ''more''.","Respond at once to every press, even by accident."]', 5, 10, null, null, '2026-09-29', '2026-11-10', 'active', '2026-09-29T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('a0b58a3f-637e-4f28-8f2e-ce32e2db09c9', '4af0f750-d9c2-4240-8024-206161c10975', '40762140-acd0-4772-b3c4-161390446dd1', '262c2456-e16d-4250-8840-7faf4b3deeb5', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Hello and bye practice', '["When someone comes home, stop at the door together.","Model ''Hi!'' or ''Namaste'' with a wave.","Wait for them to copy.","Do the same when someone leaves."]', 5, 5, null, null, '2026-10-03', '2026-11-13', 'active', '2026-10-03T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('03bbddcf-31ca-4d4c-8537-e6e2bfefbaf1', '4af0f750-d9c2-4240-8024-206161c10975', '40762140-acd0-4772-b3c4-161390446dd1', 'ccaf5264-24d0-4da7-9c61-b42634f22661', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9', 'Tiffin practice at home', '["Pack a snack in the school tiffin.","Let them open it at the table.","Show the thumb push for the bottle cap.","Only help if they ask."]', 5, 5, null, null, '2026-10-07', '2026-11-09', 'active', '2026-10-07T11:00:00.000Z', 'ac576a2f-9ce4-435c-b020-66c2abd6acb9'),
  ('4398c525-60f7-40fc-9722-d010c04c3141', '4af0f750-d9c2-4240-8024-206161c10975', '40762140-acd0-4772-b3c4-161390446dd1', 'ad2a30d0-998c-4ec9-abea-67cc3cb19411', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', 'Sorting picture cards', '["Use the picture cards from the school folder.","Make 3 piles: animals, food, vehicles.","Name each card together.","Mix and sort again."]', 4, 10, null, null, '2026-10-06', '2026-11-18', 'active', '2026-10-06T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('15e69221-c884-40c0-9a20-d77cf7c0b725', '4af0f750-d9c2-4240-8024-206161c10975', 'd6d89910-b104-4419-aa81-eeac3a3d6d51', '2c8073df-6f68-4884-b093-00bed29e2e8d', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d', '''My turn, your turn'' ball rolling', '["Sit on the floor opposite each other.","Say ''my turn'' and roll the ball.","Say ''your turn'' and wait for them to roll it back.","Play for 5 minutes, then let them choose a game."]', 5, 10, null, null, '2026-10-07', '2026-11-23', 'active', '2026-10-07T11:00:00.000Z', '8a7186b0-66cb-4898-8ca7-b5d5a4b67f3d'),
  ('9df2be38-2b60-4594-be12-608dd1926f0d', '4af0f750-d9c2-4240-8024-206161c10975', 'd6d89910-b104-4419-aa81-eeac3a3d6d51', 'f64ecbbb-0433-4efe-abde-c79cd9a2d569', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Picture book questions', '["Open a picture book you both like.","Ask ''What is this?'' and ''Where is the cat?''","Wait for an answer; give two choices if stuck.","Read the page together after each answer."]', 4, 10, null, null, '2026-10-02', '2026-11-26', 'active', '2026-10-02T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('2a450092-593c-439c-8961-dc4f84e576c5', '4af0f750-d9c2-4240-8024-206161c10975', '4a0215e9-f5a7-4a53-98c7-b707d8d7e4dd', '811b1e2e-7214-43ee-83ba-4f85e7545c71', 'c92376df-53dc-440e-8268-fcf0c8dc2011', 'Name game', '["Call their name once from 1–2 metres away.","Wait 3 seconds.","When they look, give a big smile and a small treat.","Do it 5 times through the day, not all at once."]', 5, 5, null, null, '2026-10-06', '2026-11-10', 'active', '2026-10-06T11:00:00.000Z', 'c92376df-53dc-440e-8268-fcf0c8dc2011'),
  ('e8bff4a2-c3ac-4d0c-a610-768366b94225', '4af0f750-d9c2-4240-8024-206161c10975', '4a0215e9-f5a7-4a53-98c7-b707d8d7e4dd', '4daf3e2a-02a8-49c6-a0e3-16317eafebf9', '42fb9326-d966-4c8e-94ca-4e55da47fbe9', 'New food on the plate', '["Put one tiny piece of a new food on the side of the plate.","No pressure to eat — touching or smelling counts.","Eat it yourself and say what it feels like.","Note what they tried in the app."]', 5, 10, null, null, '2026-09-30', '2026-11-26', 'active', '2026-09-30T11:00:00.000Z', '42fb9326-d966-4c8e-94ca-4e55da47fbe9'),
