insert into public.announcements (id, organization_id, title, body, audience, therapy_type_id, urgent, created_at, created_by) values
  ('da83520e-93e6-47ca-8317-6c252b8850f9', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'Centre closed on 8 Nov 2026 (Diwali)', 'Anvaya CDC will be closed on 8 Nov 2026 for Diwali. Sessions that day will not run; your coordinator will offer make-up slots. Wishing all our families a happy and safe festival!', 'everyone', null, false, '2026-10-26T05:30:00.000Z', 'b4a63a23-56c5-4cc2-88eb-7ca0756ead09'),
  ('a37f1b13-55c6-486d-bce2-60c7abcaffb5', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'Parent workshop: managing meltdowns at home', 'This Saturday, 11:00 AM–12:30 PM in Classroom B. Mr. Arjun Mehta will share simple strategies for transitions and waiting. Siblings welcome; tea and snacks provided. Reply in the care-team chat if you plan to attend.', 'all_parents', null, false, '2026-10-23T10:30:00.000Z', '55b158f3-88f2-4ec3-a2c1-2a5dccd9adf5'),
  ('e23e71db-ee7e-432a-b78e-4ae0902f9efd', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'Schedule change: Ms. Pooja Malhotra on leave', 'Ms. Pooja is on leave until 31 Oct 2026. Her sessions are being covered by other therapists. If your child''s session is affected you will get a separate notification.', 'everyone', null, true, '2026-10-28T05:00:00.000Z', '55b158f3-88f2-4ec3-a2c1-2a5dccd9adf5'),
  ('6cfb554d-849c-46ce-923d-e88a68446f11', '0580e311-3b6f-4fd3-b86d-20ef652ac6ad', 'Monthly case review — Friday 4:30 PM', 'Please bring 2 children each whose goals need discussion. Meera will share the attention list on Thursday.', 'all_staff', null, false, '2026-10-25T04:00:00.000Z', 'b4a63a23-56c5-4cc2-88eb-7ca0756ead09'),
  ('a26eb509-8f54-46ab-a0c8-1f97e1eb44c5', '4af0f750-d9c2-4240-8024-206161c10975', 'Centre closed on 1 Nov 2026 (Kannada Rajyotsava)', 'Sahaj will be closed on 1 Nov 2026 for Kannada Rajyotsava. Sessions that day will not run; your coordinator will offer make-up slots. Wishing all our families a happy and safe festival!', 'everyone', null, false, '2026-10-26T05:30:00.000Z', '511c85e0-c4fd-49d9-9112-ea44a501eac1'),
  ('ce5853c6-ae79-49db-b073-f9e4bd75dfa1', '4af0f750-d9c2-4240-8024-206161c10975', 'Sensory-friendly Deepavali tips', 'Crackers can be hard for our children. We have added a short guide to Resources — ear defenders, a quiet room plan and a picture story you can read together.', 'all_parents', null, false, '2026-10-21T09:30:00.000Z', '067be50a-76ed-4d22-896c-052187643dc9')
